Method.Source:
    /// <summary>
    /// Validating 4 parameters are populated for MET Azure storage
    /// </summary>
    /// <returns>true if validation successful; otherwise, false.</returns>
    boolean validateWrite()
    {
        boolean ret = next validateWrite();

        if (this.FilePlace == DocuFilePlace::METAzureStorage 
        && (strLen(this.METAzureStorageAccountName) < 1 || strLen(this.METAzureStorageContainerName) < 1 || strLen(this.METAzureStorageFolder) < 1 || strLen(this.METAzureStorageSecret) < 1))
        {
            ret = checkFailed(
                    strFmt('@ApplicationFoundation:DocuType_SharePointWriteError', '@MET:AzureStorageAddress',
                    fieldId2pname(tableNum(DocuType), fieldNum(DocuType, FilePlace)), DocuFilePlace::METAzureStorage))
                && ret;
        }

        return ret;
    }
